请对以下 case 进行三维加权评分。

=== case_id ===
Case-003-01-low-power-003

=== 用户原始指令 (query.txt) ===
帮我弄个低电卡片吧，字浮在背景图上那种，点能跳app，能读日历日程，提醒我快没电了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个低电卡片吧，字浮在背景图上那种，点能跳app，能读日历日程，提醒我快没电了",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModel": {
    "value": {
      "power": {
        "title": "快没电了",
        "levelText": "电量 12%",
        "hint": "低电模式提醒",
        "actionText": "打开电池"
      },
      "data": {
        "calendar": {
          "items": []
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "low_power_bg",
      "src": "assets/low-power-stage.png",
      "use": "background image",
      "description": "深色低电量氛围背景图，适合承载浮层文字和警示状态。",
      "static": true
    },
    {
      "assetRef": "battery_warning_icon",
      "src": "assets/battery-warning-icon.png",
      "use": "status icon",
      "description": "电池警示图标，可用于表达设备电量不足。",
      "static": true
    }
  ]
}

